WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE TRUE),
mk_counts AS MATERIALIZED (SELECT mk.movie_id, COUNT(*)::HUGEINT AS n FROM movie_keyword mk JOIN selected_titles eligible ON eligible.id=mk.movie_id WHERE mk.keyword_id=10890 GROUP BY mk.movie_id)
SELECT COALESCE(SUM(mk.n),0) FROM selected_titles t JOIN mk_counts mk ON mk.movie_id=t.id;

WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE TRUE),
mc_counts AS MATERIALIZED (SELECT mc.movie_id, COUNT(*)::HUGEINT AS n FROM movie_companies mc JOIN selected_titles eligible ON eligible.id=mc.movie_id WHERE TRUE GROUP BY mc.movie_id)
SELECT COALESCE(SUM(mc.n),0) FROM selected_titles t JOIN mc_counts mc ON mc.movie_id=t.id;
